     * capitalized and the remaining letters lower-cased (e.g. {@code "new york"} becomes
     * {@code "New York"}). Returns {@code null} for a {@code null} input.
     */
    private String resolveCity(Owner owner) {
        String city = owner.getCity();
        if (city == null) {
