        }
        String normalized = normalize(city);
        return ownerRepository.findAll().stream()
            .map(Owner::getCity)
            .filter(existing -> Objects.equals(normalize(existing), normalized))
            .findFirst()
            .orElseGet(() -> toTitleCase(city));
    }

    /**
