/**
 * Thrown when an attempt is made to create an <code>Owner</code> once the maximum number of
 * owners allowed to be registered on a single day (by registration date) has already been reached.
 */
public class DailyOwnerRegistrationLimitExceededException extends RuntimeException {

    public DailyOwnerRegistrationLimitExceededException() {
        super("The maximum number of owners that can be registered today has already been reached");
    }

    public DailyOwnerRegistrationLimitExceededException(String message) {
        super(message);
    }
}

